  ?ahu rdfs:label ?l . FILTER ?l LIKE "%AHU%".
  ?ahu brick:feeds ?zone .
} LIMIT 50

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?s ?class ?sid WHERE {
  ?s a brick:AirTemperatureSensor ; brick:hasLocation ?loc .
  OPTIONAL { ?s ref:hasTimeseriesId ?sid } .
}

